public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] args = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type t = args[i];
        if (t instanceof Class<?>) {
            result[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) t).getRawType();
            if (raw instanceof Class<?>) {
                result[i] = (Class<?>) raw;
            } else {
                return null;
            }
        } else if (t instanceof TypeVariable<?>) {
            // Attempt to resolve type variable using targetType's type parameters
            TypeVariable<?> tv = (TypeVariable<?>) t;
            // Build a map of type variable to actual type from targetType
            Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
            Class<?> current = targetType;
            while (current != null) {
                Type genericSuper = current.getGenericSuperclass();
                if (genericSuper instanceof ParameterizedType) {
                    ParameterizedType pSuper = (ParameterizedType) genericSuper;
                    TypeVariable<?>[] vars = current.getTypeParameters();
                    Type[] actuals = pSuper.getActualTypeArguments();
                    for (int j = 0; j < vars.length; j++) {
                        typeVarMap.put(vars[j], actuals[j]);
                    }
                }
                for (Type iface : current.getGenericInterfaces()) {
                    if (iface instanceof ParameterizedType) {
                        ParameterizedType pIface = (ParameterizedType) iface;
                        TypeVariable<?>[] vars = current.getTypeParameters();
                        Type[] actuals = pIface.getActualTypeArguments();
                        for (int j = 0; j < vars.length; j++) {
                            typeVarMap.put(vars[j], actuals[j]);
                        }
                    }
                }
                current = current.getSuperclass();
            }
            Type resolved = typeVarMap.get(tv);
            if (resolved instanceof Class<?>) {
                result[i] = (Class<?>) resolved;
            } else if (resolved instanceof ParameterizedType) {
                Type raw = ((ParameterizedType) resolved).getRawType();
                if (raw instanceof Class<?>) {
                    result[i] = (Class<?>) raw;
                } else {
                    return null;
                }
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return result;
}

