public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (true) {
        boolean isPrime = true;
        if (candidate == 2) {
            isPrime = true;
        } else if (candidate % 2 == 0) {
            isPrime = false;
        } else {
            int sqrt = (int) Math.sqrt(candidate);
            for (int i = 3; i <= sqrt; i += 2) {
                if (candidate % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2;
        if (desiredCapacity >= 1000) {
            int max = (int) (desiredCapacity * 1.11);
            if (candidate > max) {
                // If no prime found within 11%, return the first prime found
                return candidate;
            }
        }
    }
}

