final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Find the offset of the desired constant pool entry
    int offset = 10; // after magic(4), minor(2), major(2), constant_pool_count(2)
    int currentIndex = 1;
    while (currentIndex < constantPoolEntryIndex) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: case 4: // CONSTANT_Integer, CONSTANT_Float
                offset += 4;
                break;
            case 5: case 6: // CONSTANT_Long, CONSTANT_Double
                offset += 8;
                currentIndex++; // these take up two entries
                break;
            case 7: case 8: // CONSTANT_Class, CONSTANT_String
                offset += 2;
                break;
            case 9: case 10: case 11: // CONSTANT_Fieldref, CONSTANT_Methodref, CONSTANT_InterfaceMethodref
                offset += 4;
                break;
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            case 15: // CONSTANT_MethodHandle
                offset += 3;
                break;
            case 16: // CONSTANT_MethodType
                offset += 2;
                break;
            case 18: // CONSTANT_InvokeDynamic
                offset += 4;
                break;
            case 20: case 21: // CONSTANT_Module, CONSTANT_Package
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
        }
        currentIndex++;
    }

    // Read the CONSTANT_Utf8 entry
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    offset++;
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    byte[] bytes = new byte[length];
    System.arraycopy(classFileBuffer, offset, bytes, 0, length);
    String result = new String(bytes, 0, length, java.nio.charset.StandardCharsets.UTF_8);

    // Copy into the provided char buffer if it is large enough
    int copyLen = Math.min(result.length(), charBuffer.length);
    result.getChars(0, copyLen, charBuffer, 0);

    return result;
}

