private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>(keys.size());
    List<Integer> sorted = new ArrayList<>();
    for (K k : keys) {
        sorted.add((Integer) k);
    }
    Collections.sort(sorted);
    for (K k : keys) {
        Integer key = (Integer) k;
        int idx = Collections.binarySearch(sorted, key);
        if (idx >= 0) {
            result.add(key);
        } else {
            int insertPos = -idx - 1;
            if (insertPos == 0) {
                result.add(null);
            } else {
                result.add(sorted.get(insertPos - 1));
            }
        }
    }
    return result;
}

private void pop(final String descriptor) {
    int i = 0;
    if (descriptor.charAt(0) == '(') {
        i++; // skip '('
        while (descriptor.charAt(i) != ')') {
            // skip one argument type
            char c = descriptor.charAt(i);
            if (c == '[') {
                while (descriptor.charAt(i) == '[') i++;
                c = descriptor.charAt(i);
            }
            if (c == 'L') {
                i = descriptor.indexOf(';', i) + 1;
            } else {
                i++;
            }
            pos--; // pop argument type
        }
        i++; // skip ')'
        // pop return type if not void
        if (descriptor.charAt(i) != 'V') {
            char c = descriptor.charAt(i);
            if (c == '[') {
                while (descriptor.charAt(i) == '[') i++;
                c = descriptor.charAt(i);
            }
            if (c == 'L') {
                i = descriptor.indexOf(';', i) + 1;
            } else {
                i++;
            }
            pos--; // pop return type
        }
    } else {
        // single type descriptor
        char c = descriptor.charAt(i);
        if (c == '[') {
            while (descriptor.charAt(i) == '[') i++;
            c = descriptor.charAt(i);
        }
        if (c == 'L') {
            i = descriptor.indexOf(';', i) + 1;
        } else {
            i++;
        }
        pos--; // pop type
    }
}

